async function api(path,data,method=data===undefined?'GET':'POST') {
  const response=await fetch(path,{method,headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});
  const value=await response.json();if(!response.ok){const error=new Error(value.error?.message||'请求失败');error.code=value.error?.code;throw error;}return value;
}
