function renderScenes(){const source=scenes[state.session?.scene||state.scene]||scenes.work;document.querySelector('.scene-actions').hidden=Boolean(state.session)||state.assistantSurface;$('#scene-chips').hidden=Boolean(state.session);$('#mascot').hidden=state.assistantSurface;$('#scene-chips').innerHTML=source.map((s,i)=>`<button class="scene-chip ${state.scenePreset===i?'selected':''}" data-scene-prompt="${i}">${icon(s[0])}${esc(s[1])}</button>`).join('');let sub=$('#scene-subchips');if(!sub){sub=document.createElement('div');sub.id='scene-subchips';sub.className='scene-subchips';$('.scene-actions').after(sub);}sub.hidden=state.scenePreset===null||Boolean(state.session)||state.assistantSurface;const item=source[state.scenePreset];const presets=item&&state.scene==='design'?state.designScenes.find(e=>e.name===item[1])?.prompts:[];sub.innerHTML=state.scenePreset!==null?`${(presets?.length?presets:[{title:'描述我的需求',text:item?.[2]||''}]).map((p,i)=>`<button class="scene-chip" data-scene-preset="${i}">${esc(p.title)}</button>`).join('')}<button class="scene-subclose icon-button" data-close-scene-presets aria-label="收起场景模板">${icon('close')}</button>`:'';}
function useScenePreset(index){const item=(scenes[state.scene]||scenes.work)[state.scenePreset],presets=state.scene==='design'?state.designScenes.find(e=>e.name===item?.[1])?.prompts:[],preset=presets?.length?presets[index]:{text:item?.[2]};if(!preset?.text)throw Error('没有这个场景模板。');const text=preset.text+(state.scene==='design'?'\n\n只使用当前宿主实际提供的工具。缺少媒体或发布服务时先说明需要的配置，不伪造生成、上传或发布成功。':'');const apply=()=>{$('#prompt').value=text;$('#prompt').dispatchEvent(new Event('input'));$('#prompt').focus();};if($('#prompt').value.trim()&&$('#prompt').value!==text)confirmAction('替换当前草稿？','当前尚未发送的内容会被此场景模板替换。',apply,{label:'采用模板'});else apply();}

