$('#automation-form').addEventListener('submit',async event=>{event.preventDefault();try{const fd=new FormData(event.target),f=Object.fromEntries(fd),type=f.scheduleType;
  const schedule={type,...(type==='once'?{at:`${f.at}+08:00`}:type==='interval'?{intervalMinutes:Number(f.intervalMinutes)}:{time:f.time,timeZone:'Asia/Shanghai'})};
  if(['weekly','biweekly'].includes(type))schedule.weekdays=fd.getAll('weekdays').map(Number);if(type==='biweekly')schedule.anchorDate=f.anchorDate;
  if(['monthly','yearly'].includes(type))schedule.day=Number(f.day);if(type==='yearly')schedule.month=Number(f.month);for(const k of ['startDate','endDate'])if(f[k])schedule[k]=f[k];
  await api(`/api/automations${state.automationEdit?`/${state.automationEdit}`:''}`,{name:f.name,prompt:f.prompt,workspaceId:f.workspaceId,mode:f.mode,model:f.model,expertId:f.expertId,skills:fd.getAll('skills'),schedule},state.automationEdit?'PATCH':'POST');$('#automation-dialog').close();await refreshData();toast('定时任务已保存。');}catch(error){toast(error.message);}});

